      join digest.member_state_snapshot s on s.at_member_id = ma.at_member_id
      cross join lateral (values
        ('membership_status', s.membership_status, ma.membership_status),
        ('chapter_affiliation', s.chapter_affiliation, ma.chapter_affiliation::text),
        ('rev_band', s.rev_band, ma.rev_band),
